style.css:
@-moz-document domain("google.com") {
body, #gsr, #main, .cnt {
        background-image: url("https://ru.pinterest.com/pin/598908450473975127/") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        background-repeat: no-repeat !important;
        color: #FFFFFF !important;
    }
    
    a, h3, .LC20lb {
        color: #C8102E !important;
    }
    
    a:hover, h3:hover {
        color: #FFFFFF !important;
        text-shadow: 0 0 10px #C8102E !important;
    }

    textarea, input[type="text"], .gLFyf {
        background-color: #FFFFFF !important;
        color: #000000 !important;
        border: 3px solid #C8102E !important;
        border-radius: 24px !important;
    }

    input[type="submit"], button, .gNO89b, .RNmpXc {
        background: linear-gradient(135deg, #004B87 50%, #C8102E 50%) !important;
        color: #FFFFFF !important;
        border: 2px solid #FFFFFF !important;
        border-radius: 20px !important;
        font-weight: bold !important;
    }

    .RNNXgb, .sbi_b {
        background-color: #FFFFFF !important;
        border: 3px solid #004B87 !important;
    }

    .FAw9bc, .RNNXgb {
        box-shadow: 0 4px 10px rgba(0, 75, 135, 0.5) !important;
    }
}
